'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t,glyphs=['☀','☾','◆'];
const names=[['Sun','太陽'],['Moon','月亮'],['Diamond','菱形']];
let variant=OrionProgress.variant('compression'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget;
let stage=0,pairs=[],decoded=[],symbol=0,count=1,choice='',preview=false,solved=false,hintDepth=0,state='ready',saveFailed=false;
function encode(seq){const out=[];for(const x of seq){if(out.length&&out[out.length-1][0]===x)out[out.length-1][1]++;else out.push([x,1]);}return out;}
function decode(tokens){return tokens.flatMap(([x,n])=>Array(n).fill(x));}
function target(v=variant,s=stage){const a=v%3,b=(a+1)%3,c=(a+2)%3;if(s===0)return decode([[a,3+v%2],[b,2],[c,3]]);if(s===1)return decode([[c,2],[a,2+v%2],[b,1]]);return v%3===0?[a,b,a,b,a,b]:v%3===1?decode([[a,4],[b,3]]):decode([[a,2],[b,2],[c,2]]);}
function resetTrial(){pairs=[];decoded=[];symbol=0;count=1;choice='';preview=false;solved=false;hintDepth=0;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('compression')){variant=v;stage=0;resetTrial();}
function chooseSymbol(x){if(solved||stage===2||!Number.isInteger(x)||x<0||x>2)return;if(stage===0)symbol=x;else if(decoded.length<16)decoded.push(x);else return;preview=false;state='ready';render();$('symbol'+x).focus();}
function setCount(n){if(solved||stage!==0||!Number.isInteger(n)||n<1||n>9)return;count=n;render();}
function pack(){if(solved||stage!==0||pairs.length>=12)return;pairs.push([symbol,count]);preview=false;state='ready';render();}
function undo(){if(solved||stage===2)return;if(stage===0)pairs.pop();else decoded.pop();preview=false;state='ready';render();}
function choose(x){if(solved||stage!==2||!['raw','packed','equal'].includes(x))return;choice=x;state='ready';render();}
function best(){const n=target().length,c=encode(target()).length*2;return n<c?'raw':n>c?'packed':'equal';}
function check(){if(solved)return;const expected=target();if(stage===0){preview=true;const actual=decode(pairs);if(actual.join()!==expected.join())state='mismatch';else if(pairs.length!==encode(expected).length)state='split';else solved=true;}else if(stage===1){if(decoded.join()===expected.join())solved=true;else state='mismatch';}else if(!choice)state='choose';else if(choice===best())solved=true;else state='cost';if(solved){state='success';if(stage===2)saveFailed=!OrionProgress.earn('memory');}render();if(solved&&stage<2)$('next').focus();}
function sequenceLabel(seq){return seq.length?seq.map(x=>t(...names[x])).join(', '):t('Empty message','空白訊息');}
function tokenLabel(tokens){return tokens.map(([x,n])=>`${t(...names[x])} × ${n}`).join(', ');}
function tiles(seq){return seq.map(x=>`<span class="tile" aria-hidden="true">${glyphs[x]}</span>`).join('');}
function tokens(ts){return ts.map(([x,n])=>`<span class="token" aria-hidden="true">${glyphs[x]} <b>×${n}</b></span>`).join('');}
function hints(){const seq=target(),runs=encode(seq);return [t('Read from left to right. Only neighbours with the same rune belong to one run. Keep the order.','由左至右閱讀。只有相鄰相同符文才屬同一段。保留次序。'),stage===2?t('Count 1 slot for each original rune, and 2 for each packed pair. Packing is not always smaller.','每個原符文算 1 格，每組打包配對算 2 格。打包不一定較小。'):t('A pair such as Sun × 3 restores Sun, Sun, Sun. A count tells how many copies to restore.','例如「太陽 × 3」可還原成太陽、太陽、太陽。數量表示要還原多少個。'),stage===0?t(`Pack these runs: ${tokenLabel(runs)}.`,`打包這幾段：${tokenLabel(runs)}。`):stage===1?t(`Restore: ${sequenceLabel(seq)}.`,`還原：${sequenceLabel(seq)}。`):t(`Raw: ${seq.length} slots. Packed: ${runs.length} × 2 = ${runs.length*2} slots. Compare them.`,`原文：${seq.length} 格。打包：${runs.length} × 2 = ${runs.length*2} 格。比較兩者。`)];}
function render(){const seq=target(),runs=encode(seq),complete=solved&&stage===2,progress=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Whispering Archive · Orion','低語檔案館 · Orion');$('stageTitle').textContent=t(`Scroll ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 卷 · 第 ${variant+1} 組`);$('sceneStatus').textContent=t(`Archive seals · ${progress} / 3`,`檔案館封印 · ${progress} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<progress?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);
$('instruction').textContent=[t('Choose a rune and its repeat count. Pack each run in order, then send your parcel.','選符文和重複數量，依次打包每一段，再傳送包裹。'),t('Read each packed pair. Tap the rune buttons to rebuild the original message in order.','閱讀每組配對，點符文按鈕，按次序重建原文。'),t('Which uses fewer storage slots? Choose raw, packed, or same size, then send.','哪個佔較少儲存格？選原文、打包或一樣大，再傳送。')][stage];
$('sourceTitle').textContent=stage===1?t('Received parcel · rune × count','收到的包裹 · 符文 × 數量'):t('Original message','原始訊息');$('source').innerHTML=stage===1?tokens(runs):tiles(seq);$('source').setAttribute('aria-label',stage===1?tokenLabel(runs):sequenceLabel(seq));
$('workbench').hidden=stage===2;$('packing').hidden=stage!==0;$('expand').hidden=stage!==0;$('expand').disabled=solved||!pairs.length;$('add').disabled=solved||pairs.length>=12;$('undo').disabled=solved||!(stage===0?pairs.length:decoded.length);$('count').innerHTML=Array.from({length:9},(_,i)=>`<option value="${i+1}">${i+1}</option>`).join('');$('count').value=count;$('count').disabled=solved;
$('symbols').innerHTML=names.map((n,i)=>`<button id="symbol${i}" ${solved?'disabled':''} ${stage===0?`aria-pressed="${symbol===i}"`:''}>${glyphs[i]} ${t(...n)}</button>`).join('');names.forEach((_,i)=>$('symbol'+i).onclick=()=>chooseSymbol(i));
$('parcel').innerHTML=stage===0?tokens(pairs):tiles(decoded);$('parcel').setAttribute('aria-label',stage===0?tokenLabel(pairs)||t('Empty parcel','空白包裹'):sequenceLabel(decoded));
$('choices').hidden=stage!==2;$('choices').innerHTML=['raw','packed','equal'].map((x,i)=>`<button id="choice${i}" aria-pressed="${choice===x}" ${solved?'disabled':''}>${[t('Original runes','原文符文'),t('Packed pairs','打包配對'),t('Same size','一樣大')][i]}</button>`).join('');['raw','packed','equal'].forEach((x,i)=>$('choice'+i).onclick=()=>choose(x));
$('goal').textContent=[t('Seal 1: restore every rune exactly, using one pair for each full run of identical neighbours.','封印 1：完整還原每個符文，每段相鄰相同符文只用一組配對。'),t('Seal 2: rebuild the received message exactly. Keep every rune and its order.','封印 2：完整重建收到的訊息，保留每個符文及次序。'),t('Seal 3: choose the smaller form under our storage rule, or select Same size if tied.','封印 3：按儲存規則選較小的格式，相同則選「一樣大」。')][stage];
if(stage===0){$('reading').innerHTML=preview?`<span>${t('Unpacked preview','解開後預覽')}</span><div class="rune-strip">${tiles(decode(pairs))}</div>`:t('Your unpacked preview will appear here.','解開後的預覽會在這裡顯示。');$('reading').setAttribute('aria-label',preview?sequenceLabel(decode(pairs)):t('Preview not opened','尚未打開預覽'));}else if(stage===1){$('reading').textContent=t(`Rebuilt: ${decoded.length} runes`,`已重建：${decoded.length} 個符文`);$('reading').removeAttribute?.('aria-label');}else{$('reading').innerHTML=`${t('Packed version','打包版本')}<div class="rune-strip">${tokens(runs)}</div>`;$('reading').setAttribute('aria-label',tokenLabel(runs));}
$('evidence').textContent=stage===0?t(`Parcel cost: ${pairs.length*2} slots`,`包裹佔：${pairs.length*2} 格`):stage===2?t(`Original: ${seq.length} slots · Packed: ${runs.length*2} slots`,`原文：${seq.length} 格 · 打包：${runs.length*2} 格`):'';
const messages={ready:t('Try your idea. You can undo or clear and try again.','試試你的想法。可以撤回或清空再試。'),mismatch:t('The runes or their order do not match yet. Compare from the left; undo or clear to try again.','符文或次序還不相同。從左開始比較，撤回或清空再試。'),split:t('Every rune is correct! Now combine neighbouring identical pairs into one full run.','每個符文都正確！現在把相鄰相同配對合成完整的一段。'),choose:t('Choose one of the three storage answers first.','先選一個儲存答案。'),cost:t('Compare the two slot counts. Remember: each pair needs a rune AND a count.','比較兩個格數。記住：每組配對需要符文和數量。'),success:stage===2?t('Correct comparison! Packing can save space, stay equal, or make a message larger.','比較正確！打包可能省空間、大小相同，也可能變大。'):t('Every rune is restored in order. An archive seal glows!','每個符文都依次還原，檔案館封印亮起了！')};$('feedback').textContent=messages[state];$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('memory')?t('Memory Sigil saved in your collection.','記憶符印已存入收藏。'):'';}
$('count').onchange=()=>setCount(Number($('count').value));$('add').onclick=pack;$('undo').onclick=undo;$('expand').onclick=()=>{preview=true;render();};$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();$('check').focus();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('compression',variant);observedVariant=OrionProgress.variant('compression');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('memory');render();};
function syncProgress(){const v=OrionProgress.variant('compression'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('memory')&&!saveFailed)resetMission();else render();}
window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
